WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_conc_sc_pour_add'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '倒出又加水', 'kp-conc-sc-pour-add', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "倒出又加水"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "倒出溶液，浓度不变，但溶质按比例减少。加满水，溶液总量恢复。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“一杯 100克 20%的盐水，倒出 1/4 后，加满清水。求新浓度？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、极速秒杀法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "倒出 1/4，说明杯子里还剩 3/4 的盐！后来加满了水，说明杯子总重量恢复到 100克！"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "所以：新浓度 = 原浓度 × (1 - 倒出的比例) = 20% × 3/4 = 15%。"}]}]}$$ AS jsonb), NULL, '倒出又加水的核心考点与实战推导。', category_node.id, CAST('["数量关系", "浓度问题", "倒出又加水"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_conc_sc_pour_add", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
